import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        for (int i = 0; i < n; i++) {
            in.next();
            String a = in.next();
            String b = in.next();
            if (a.equals("up") && b.equals("up")) {
                System.out.println("WORKS");
            } else if (a.equals("up")) {
                System.out.println("LAYER2");
            } else {
                System.out.println("CABLE");
            }
        }
    }
}

